$ErrorActionPreference='Stop'
function Assert($v,$why){if(-not $v){throw $why}}
function Symbols($name){$sy=@{};Get-Content (Join-Path $PSScriptRoot ($name+'.sym'))|ForEach-Object{if($_ -match '^v0\.([^:]+): EQU 0x([0-9A-Fa-f]+)'){$sy[$matches[1]]=[Convert]::ToInt32($matches[2],16)}};return $sy}
$terminal=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'terminal11_el_mb_setup.bin'));Assert ($terminal.Length -eq 5256) 'Terminal 1.1 component size'
foreach($spec in @(@('wifi_setup_standalone','wifi_setup_standalone18',16184),@('wifi_setup_flash','wifi_setup_flash18',16228),@('wifi_setup_flash_debug','wifi_setup_flash18_debug',16228))){$sy=Symbols $spec[0];$bytes=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot $spec[1]));Assert ($bytes.Length -eq $spec[2] -and $bytes.Length -lt 16384) 'Output size/limit';Assert ($sy.terminal_start -eq 30000 -and $sy.terminal_len -eq 5256 -and $sy.AP_list_start -eq 35256) 'Terminal/AP layout';$offset=$sy.terminal_code-49152;if($spec[0] -ne 'wifi_setup_standalone'){$offset+=$sy.strt_len};for($i=0;$i -lt $terminal.Length;$i++){Assert ($bytes[$offset+$i] -eq $terminal[$i]) 'Embedded terminal 1.1 differs'};$bios=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'WifiBios21_MB_EL.cod'));$offset=$sy.bios_start-49152;if($spec[0] -ne 'wifi_setup_standalone'){$offset+=$sy.strt_len};for($i=0;$i -lt $bios.Length;$i++){Assert ($bytes[$offset+$i] -eq $bios[$i]) 'BIOS 2.1 differs'}}
$tap=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'wifi_setup_standalone18.tap'));$blocks=[Collections.Generic.List[byte[]]]::new();$p=0;while($p -lt $tap.Length){Assert ($p+2 -le $tap.Length) 'TAP truncated';$len=[BitConverter]::ToUInt16($tap,$p);$p+=2;Assert ($len -ge 2 -and $p+$len -le $tap.Length) 'TAP length';[byte[]]$part=$tap[$p..($p+$len-1)];$xor=0;foreach($b in $part){$xor=$xor-bxor $b};Assert ($xor -eq 0) 'TAP checksum';$blocks.Add($part);$p+=$len};Assert ($blocks.Count -eq 4 -and $tap.Length -eq 16264) 'TAP release size';Assert ([BitConverter]::ToUInt16($blocks[2],14) -eq 49152) 'TAP load address';$loader=[Text.Encoding]::ASCII.GetString($blocks[1]);Assert ($loader.Contains('27647') -and -not $loader.Contains('29999')) 'BASIC stack must be below history/editor scratch';$raw=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'wifi_setup_standalone18'));Assert ($blocks[3].Length -eq $raw.Length+2) 'CODE length';for($i=0;$i -lt $raw.Length;$i++){Assert ($blocks[3][$i+1] -eq $raw[$i]) 'CODE payload differs'}
'PASS: terminal 1.1 and BIOS 2.1 embedded in all 3 variants; memory map, limits, loader CLEAR, TAP checksums/payload.'